/// Finds a frozen v1 operation by its shared operation identifier.
#[must_use]
pub fn operation_by_id(operation_id: &str) -> Option<&'static OperationContract> {
    OPERATIONS
        .iter()
        .find(|operation| operation.operation_id == operation_id)
}
